  gy=np.zeros_like(lum);gx=np.zeros_like(lum); gy[1:-1]=lum[2:]-lum[:-2];gx[:,1:-1]=lum[:,2:]-lum[:,:-2];a=np.hypot(gx,gy)
 elif mode=='yellow': a=np.maximum(0, np.minimum(im[:,:,0]-im[:,:,2], im[:,:,1]-im[:,:,2]))
 else:a=255-lum
 for by in range(0,144,4):
  s=''
